-- Migration: 020_restore_missing_headshot_styles
-- Description: Restore missing headshot style rows on existing databases without rewriting historical migrations.

BEGIN;

ALTER TABLE headshot_styles
  ADD COLUMN IF NOT EXISTS category_order INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS style_order INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS selection_count INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS last_selected_at TIMESTAMP WITH TIME ZONE,
  ADD COLUMN IF NOT EXISTS localized_names JSONB NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS localized_category_labels JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE INDEX IF NOT EXISTS idx_headshot_styles_category_order ON headshot_styles(category_order, style_order);
CREATE INDEX IF NOT EXISTS idx_headshot_styles_selection_count ON headshot_styles(selection_count DESC, last_selected_at DESC);
CREATE INDEX IF NOT EXISTS idx_headshot_styles_localized_names ON headshot_styles USING GIN (localized_names);

ON CONFLICT (id) DO NOTHING;

UPDATE headshot_styles
SET
  category_order = CASE category
    WHEN 'professional' THEN 1
    WHEN 'lifestyle' THEN 2
    WHEN 'artistic' THEN 3
    WHEN 'seasonal' THEN 4
    WHEN 'photo_tools' THEN 5
    ELSE 9
  END,
  style_order = sort_order,
  localized_category_labels = COALESCE(localized_category_labels, '{}'::jsonb) ||
    CASE category
      WHEN 'professional' THEN jsonb_build_object('es', 'Profesional', 'fr', 'Professionnel', 'de', 'Professionell', 'ja', 'Professional')
      WHEN 'artistic' THEN jsonb_build_object('es', 'Creativo', 'fr', 'Creatif', 'de', 'Kreativ', 'ja', 'Creative')
      WHEN 'lifestyle' THEN jsonb_build_object('es', 'Lifestyle', 'fr', 'Style de vie', 'de', 'Lifestyle', 'ja', 'Lifestyle')
      WHEN 'seasonal' THEN jsonb_build_object('es', 'Temporada', 'fr', 'Saisonnier', 'de', 'Saisonal', 'ja', 'Seasonal')
      WHEN 'photo_tools' THEN jsonb_build_object('es', 'Foto para imprimir', 'fr', 'Photo a imprimer', 'de', 'Druckfoto', 'ja', 'Print Photo')
      ELSE '{}'::jsonb
    END,
  updated_at = NOW()
