  'startup_founder', 'podcast_host', 'gamer_streamer', 'travel_creator',
  'fitness_brand', 'beauty_influencer', 'music_artist', 'fashion_portrait',
  'cinematic_portrait', 'summer_sunshine', 'beach_golden_hour', 'city_street',
  'coffee_shop', 'autumn_park', 'library_study', 'garden_spring',
  'spring_blossom', 'autumn_foliage', 'winter_snow', 'black_white_classic',
